func Or(predicates ...predicate.DownloadConfig) predicate.DownloadConfig {
	return predicate.DownloadConfig(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DownloadConfig) predicate.DownloadConfig {
	return predicate.DownloadConfig(sql.NotPredicates(p))
}
